class Problem {
    // You are given an array array list of numbers.
    // You need to return the sum of squared numbers in the given array list,
    // round each element in the array list to the upper int(Ceiling) first.
    // Examples:
    // >>> lst((new ArrayList<Float>(Arrays.asList((float)1.0f, (float)2.0f, (float)3.0f))))
    // (14l)
    // >>> lst((new ArrayList<Float>(Arrays.asList((float)1.0f, (float)4.0f, (float)9.0f))))
    // (98l)
    // >>> lst((new ArrayList<Float>(Arrays.asList((float)1.0f, (float)3.0f, (float)5.0f, (float)7.0f))))
    // (84l)
    // >>> lst((new ArrayList<Float>(Arrays.asList((float)1.4f, (float)4.2f, (float)0.0f))))
    // (29l)
    // >>> lst((new ArrayList<Float>(Arrays.asList((float)-2.4f, (float)1.0f, (float)1.0f))))
    // (6l)
    public static long sumSquares(ArrayList<Float> lst) {
        if (lst.size() == 0) {
            return 0;
        }
        long sum = 0;
        for (int i = 0; i < lst.size(); i++) {
            sum += (long)Math.ceil(lst.get(i)) * (long)Math.ceil(lst.get(i));
        }
        return sum;
    }

package org.apache.synapse.endpoints;

import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import org.apache.axis2.AxisFault;
import org.apache.axis2.addressing.EndpointReference;
import org.apache.axis2.clustering.Member;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;
import org.apache.synapse.MessageContext;
import org.apache.synapse.SynapseConstants;
import org.apache.synapse.SynapseException;
import org.apache.synapse.core.SynapseEnvironment;
import org.apache.synapse.core.axis2.Axis2MessageContext;
import org.apache.synapse.mediators.Value;
import org.apache.synapse.mediators.eip.EIPConstants;
import org.apache.synapse.util.MessageHelper;

/**
 * <p>
 * A Recipient List endpoint can contain multiple child endpoints or member elements.
 * It routes cloned copies of messages to each child recipient. This will assume that
 * all immediate child endpoints are identical in state (state is replicated) or state
 * is not maintained at those endpoints.
 * </p>
 */
public class RecipientListEndpoint extends AbstractEndpoint {

    private static final Log log = LogFactory.getLog(RecipientListEndpoint.class);

    private static final String DELIMITER = ",";

    /**
     * The list of members to which the message is delivered to
     */
    private List<Member> members;

    private Map<String, Endpoint> dynamicEndpointPool;

    private Value dynamicEndpointSet;

    public final static int DEFAULT_MAX_POOL = 20;

    /**
     * Should this recipient list fail over;
     */
    private boolean failover;

    private int currentPool;

    private SynapseEnvironment env = null;

    public RecipientListEndpoint(int poolSize) {
        dynamicEndpointPool = Collections.synchronizedMap(new DynamicEndpointPool<String, Endpoint>(poolSize));
        this.currentPool = poolSize;
    }

    public RecipientListEndpoint() {
        this.currentPool = DEFAULT_MAX_POOL;
    }

    @Override
    public void init(SynapseEnvironment synapseEnvironment) {
        if (!initialized) {
            super.init(synapseEnvironment);
        }
        this.env = synapseEnvironment;
    }

    @Override
    public void destroy() {
        super.destroy();
    }

    @Override
    public void send(MessageContext synCtx) {
        if (log.isDebugEnabled()) {
            log.debug("Sending using Recipient List " + toString());
        }
        List<Endpoint> children = getChildren();
        // Service child endpoints
        if (children != null && !children.isEmpty()) {
            sendToEndpointList(synCtx, children);
        } else if (members != null && !members.isEmpty()) {
            // Service member elements if specified
            sendToApplicationMembers(synCtx);
        } else if (dynamicEndpointSet != null) {
            sendToDynamicMembers(synCtx);
        } else {
            String msg = "No child endpoints nor members available";
            log.error(msg);
            throw new SynapseException(msg);
        }
    }

    private void sendToEndpointList(MessageContext synCtx, List<Endpoint> children) {
        int i = 0;
        boolean foundEndpoint = false;
        for (Endpoint childEndpoint : children) {
            if (childEndpoint.readyToSend()) {
                foundEndpoint = true;
                MessageContext newCtx;

                // Used when aggregating responses
                newCtx.setProperty(EIPConstants.MESSAGE_SEQUENCE, String.valueOf(i++) + EIPConstants.MESSAGE_SEQUENCE_DELEMITER + children.size());
                // evaluate the endpoint properties
                evaluateProperties(newCtx);
                newCtx.pushFaultHandler(this);
                childEndpoint.send(newCtx);
            }
        }
        if (!foundEndpoint) {
            String msg = "Recipient List endpoint : " + (getName() != null ? getName() : SynapseConstants.ANONYMOUS_ENDPOINT) + " - no ready child endpoints";
            log.warn(msg);
            informFailure(synCtx, SynapseConstants.ENDPOINT_FO_NONE_READY, msg);
        }
    }

    private void sendToDynamicMembers(MessageContext synCtx) {
        String dynamicUrlStr = dynamicEndpointSet.evaluateValue(synCtx);
        String[] dynamicUrlSet = dynamicUrlStr.split(DELIMITER);
        if (dynamicUrlSet.length == 0) {
            log.warn("No recipients were derived from the expression : " + dynamicEndpointSet.toString());
            return;
        }
        List<Endpoint> children = new ArrayList<Endpoint>();
        for (String url : dynamicUrlSet) {
            url = StringUtils.deleteWhitespace(url);
            if (StringUtils.isNotEmpty(url)) {
                // get an Endpoint from the pool
                Endpoint epFromPool = dynamicEndpointPool.get(url);
                if (epFromPool == null) {
                    AddressEndpoint endpoint = new AddressEndpoint();
                    endpoint.setEnableMBeanStats(false);
                    endpoint.setName("DYNAMIC_RECIPIENT_LIST_EP_" + UUID.randomUUID());
                    EndpointDefinition definition = new EndpointDefinition();
                    definition.setReplicationDisabled(true);
                    definition.setAddress(url);
                    endpoint.setDefinition(definition);
                    endpoint.init(env);
                    // finally add the newly created endpoint to the Pool
                    dynamicEndpointPool.put(url, endpoint);
                    children.add(endpoint);
                } else {
                    // do nothing endpoint is already in the pool
                    children.add(epFromPool);
                }
            }
        }
        if (children.size() > 0) {
            sendToEndpointList(synCtx, children);
        } else {
            if (log.isDebugEnabled()) {
                log.debug("Halted sending messages to recipients. No recipient found !!! : " + dynamicUrlStr);
            }
        }
    }

    /**
     * <p>Iterates the <b>members</b> list, creates Address Endpoints
     *  from each member element and routes cloned copies of the message
     *  to each Address Endpoint.</p>
     *  @param synCtx - The Original Message received by Synapse
     */
    private void sendToApplicationMembers(MessageContext synCtx) {
        int i = 0;
        boolean foundEndpoint = false;
        for (Member member : members) {
            org.apache.axis2.context.MessageContext axis2MsgCtx = ((Axis2MessageContext) synCtx).getAxis2MessageContext();
            String transport = axis2MsgCtx.getTransportIn().getName();
            // If the transport is not HTTP nor HTTPS
            if (!transport.equals("http") && !transport.equals("https")) {
                // Skip member.
                log.error("Cannot deliver for non-HTTP/S transport " + transport);
                continue;
            }
            MessageContext newCtx;
            try {
                newCtx = MessageHelper.cloneMessageContext(synCtx);
            } catch (AxisFault e) {
                handleException("Error cloning the message context", e);
                return;
            }
            // Used when aggregating responses
            newCtx.setProperty(EIPConstants.MESSAGE_SEQUENCE, String.valueOf(i++) + EIPConstants.MESSAGE_SEQUENCE_DELEMITER + members.size());
            // evaluate the endpoint properties
            evaluateProperties(newCtx);
            // URL rewrite
            String address = newCtx.getTo().getAddress();
            if (address.contains(":")) {
                try {
                    address = new URL(address).getPath();
                } catch (MalformedURLException e) {
                    String msg = "URL " + address + " is malformed";
                    log.error(msg, e);
                    throw new SynapseException(msg, e);
                }
            }
            EndpointReference epr = new EndpointReference(transport + "://" + member.getHostName() + ":" + ("http".equals(transport) ? member.getHttpPort() : member.getHttpsPort()) + address);
            newCtx.setTo(epr);
            newCtx.pushFaultHandler(this);
            AddressEndpoint endpoint = new AddressEndpoint();
            EndpointDefinition definition = new EndpointDefinition();
            endpoint.setDefinition(definition);
            endpoint.init(newCtx.getEnvironment());
            if (endpoint.readyToSend()) {
                foundEndpoint = true;
                endpoint.send(newCtx);
            }
        }
        if (!foundEndpoint) {
            String msg = "Recipient List endpoint : " + (getName() != null ? getName() : SynapseConstants.ANONYMOUS_ENDPOINT) + " - no ready child members";
            log.warn(msg);
            informFailure(synCtx, SynapseConstants.ENDPOINT_FO_NONE_READY, msg);
        }
    }

    @Override
    public boolean readyToSend() {
        for (Endpoint endpoint : getChildren()) {
            if (endpoint.readyToSend()) {
                if (log.isDebugEnabled()) {
                    log.debug("Recipient List " + this.toString() + " has at least one endpoint at ready state");
                }
                return true;
            }
        }
        return false;
    }

    public void onChildEndpointFail(Endpoint endpoint, MessageContext synMessageContext) {
        // we just log the failed recipient here
        logOnChildEndpointFail(endpoint, synMessageContext);
        String msg = "";
        if (log.isDebugEnabled()) {
            msg = "Recipient List endpoint : " + (getName() != null ? getName() : SynapseConstants.ANONYMOUS_ENDPOINT) + " - one of the recipients encounterd an error while sending the message ";
            log.debug(msg);
        }
        informFailure(synMessageContext, SynapseConstants.ENDPOINT_FO_NONE_READY, msg);
    }

    public List<Member> getMembers() {
        return members;
    }

    public void setMembers(List<Member> members) {
        this.members = members;
    }

    public Value getDynamicEndpointSet() {
        return dynamicEndpointSet;
    }

    public void setDynamicEndpointSet(Value dynamicEndpointSet) {
        this.dynamicEndpointSet = dynamicEndpointSet;
    }

    public int getCurrentPoolSize() {
        return currentPool;
    }

    public boolean isFailover() {
        return failover;
    }

    public void setFailover(boolean failover) {
        this.failover = failover;
    }

    /**
     * create a simple LRU cached Endpoint pool for dynamic endpoints
     */
    private static class DynamicEndpointPool<String, Endpoint> extends LinkedHashMap<String, Endpoint> {

        private final int maxPoolSize;

        public DynamicEndpointPool(final int max) {
            super(max + 1, 1.0f, true);
            this.maxPoolSize = max;
        }

        @Override
        protected boolean removeEldestEntry(final Map.Entry<String, Endpoint> eldest) {
            return super.size() > maxPoolSize;
        }
    }
}

import json
from core.crawler import Crawler
from omegaconf import OmegaConf
import requests
from attrdict import AttrDict
import logging
import base64

from ratelimiter import RateLimiter
from core.utils import create_session_with_retries

from typing import List, Any

class Github(object):
    def __init__(self, repo: str, owner: str, token: str) -> None:
        self.repo = repo
        self.owner = owner
        self.token = token
        self.session = create_session_with_retries()


    def get_issues(self, state: str) -> List[Any]:
        # state can be "open", "closed", or "all"
        api_url = f"https://api.github.com/repos/{self.owner}/{self.repo}/issues?state={state}"
        headers = {"Authorization": f"Bearer {self.token}", "Accept": "application/vnd.github+json"}
        response = self.session.get(api_url, headers=headers)
        if response.status_code == 200:
            return list(response.json())
        else:
            logging.info(f"Error retrieving issues: {response.status_code}, {response.text}")
            return []

    def get_comments(self, issue_number: str) -> List[Any]:
        api_url = f"https://api.github.com/repos/{self.owner}/{self.repo}/issues/{issue_number}/comments"
        headers = {"Authorization": f"Bearer {self.token}", "Accept": "application/vnd.github+json"}
        response = self.session.get(api_url, headers=headers)
        if response.status_code == 200:
            return list(response.json())
        else:
            logging.info(f"Error retrieving comments: {response.status_code}, {response.text}")
            return []


class GithubCrawler(Crawler):

    def __init__(self, cfg: OmegaConf, endpoint: str, customer_id: str, corpus_id: int, api_key: str) -> None:
        super().__init__(cfg, endpoint, customer_id, corpus_id, api_key)
        self.github_token = self.cfg.github_crawler.get("github_token", None)
        self.owner = self.cfg.github_crawler.owner
        self.repos = self.cfg.github_crawler.repos
        self.crawl_code = self.cfg.github_crawler.crawl_code
        self.rate_limiter = RateLimiter(max_calls=1, period=1)
        self.session = create_session_with_retries()
        adapter = requests.adapters.HTTPAdapter(max_retries=3)
        self.session.mount('http://', adapter)
        self.session.mount('https://', adapter)

    def crawl_code_folder(self, base_url: str, path: str = "") -> None:
        headers = { "Accept": "application/vnd.github+json"}
        if self.github_token:
            headers["Authorization"] = f"token {self.github_token}"
        with self.rate_limiter:
            response = self.session.get( f"{base_url}/contents/{path}", headers=headers)
        if response.status_code != 200:
            logging.info(f"Error fetching {base_url}/contents/{path}: {response.text}")
            return

        for item in response.json():
            if item["type"] == "file":
                fname = item["path"]
                url = item["html_url"]
                if url.lower().endswith(".md") or url.lower().endswith(".mdx"):     # Only index markdown files from the code, not the code itself
                    try:
                        file_response = self.session.get(item["url"], headers={"Authorization": f"token {self.github_token}"})
                        file_content = base64.b64decode(file_response.json()["content"]).decode("utf-8")
                    except Exception as e:
                        logging.info(f"Failed to retrieve content for {fname} with url {url}: {e}")
                        continue

                    metadata = {'file': fname, 'source': 'github', 'url': url}
                    code_doc = {
                        'documentId': f'github-{item["path"]}',
                        'title': item["name"],
                        'description': f'Markdown of {fname}',
                        'metadataJson': json.dumps(metadata),
                        'section': [{
                            'title': 'markdown',
                            'text': file_content,
                        }]
                    }
                    logging.info(f"Indexing codebase markdown: {item['path']}")
                    self.

        elif item["type"] == "dir":
            self.crawl_code_folder(base_url, path=item["path"])

def crawl_repo(self, repo: str, owner: str, token: str) -> None:

    g = Github(repo, owner, token)
    issues = g.get_issues("all")

    for d_issue in issues:
        # Extract issue metadata
        issue = AttrDict(d_issue)
        issue_id = f'github-issue-{issue.id}'
        title = issue.title
        description = issue.body
        created_at = str(issue.created_at)
        updated_at = str(issue.updated_at)
        labels = [label.name for label in issue.labels]
        author = issue.user.login
        metadata = {'issue_number': issue.number, 'labels': labels, 'source': 'github', 'url': issue.html_url, 'state': issue.state}

        issue_doc = {
            'documentId': f'github-issue-{issue_id}',
            'title': title,
            'description': description,
            'metadataJson': json.dumps(metadata),
            'section': [{
                'title': 'issue',
                'text': description,
                'metadataJson': json.dumps({
                    'author': author,
                    'created_at': created_at,
                    'updated_at': updated_at
                })
            }]
        }
        logging.info(f"Indexing issue: {issue.id}")
        self.indexer.index_document(issue_doc)

        # Extract and index comments
        comments = g.get_comments(issue.number)
        if len(comments)>0:
            logging.info(f"Indexing {len(comments)} comments for issue {issue.number}")
        else:
            logging.info(f"No comments for issue {issue.number}")

        for d_comment in comments:
            comment = AttrDict(d_comment)
            comment_id = comment.id
            comment_text = comment.body
            comment_author = comment.user.login
            comment_created_at = str(comment.created_at)
            metadata = {'comment_id': comment.id, 'url': comment.html_url, 'source': 'github'}

            comment_doc = {
                'documentId': f'github-comment-{comment_id}',
                'title': title,
                'description': comment_text,
                'metadataJson': json.dumps(metadata),
                'section': [{
                    'title': 'comment',
                    'text': comment_text,
                    'metadataJson': json.dumps({
                        'author': comment_author,
                        'created_at': comment_created_at,
                        'updated_at': updated_at
                    })
                }]
            }
            try:
                self.indexer.index_document(comment_doc)
            except Exception as e:
                logging.info(f"Error {e} indexing comment document {comment_doc}")
                continue

    if self.crawl_code:
        base_url = f"https://api.github.com/repos/{owner}/{repo}"
        self.crawl_code_folder(base_url)


def crawl(self) -> None:
    for repo in self.repos:
        logging.info(f"Crawling repo {repo}")
        self.crawl_repo(repo, self.owner, self.github_token)

package service;

