            } else if (currentGrade > 2.0f) {
                letterGrades.add("C+");
            } else if (currentGrade > 1.7f) {
                letterGrades.add("C");

                letterGrades.add("C-");
            } else if (currentGrade > 1.0f) {
                letterGrades.add("D+");
            } else if (currentGrade > 0.7f) {
                letterGrades.add("D");
            } else if (currentGrade > 0.0f) {
