        if (isEmpty()) {
            setHead(node);
            getHead().setNext(getHead());
        } else {
            Nodo pointer = getHead();
            node.setNext(getHead());
            while (pointer.getNext() != getHead()) {
                pointer = (Nodo) pointer.getNext();
            }
            pointer.setNext(node);
        }
        length++;
