            Nodo pointer2;

            if (length > 1){
                while (((Nodo) (pointer.getNext())).getNext() != getHead()) {
                    pointer = (Nodo) pointer.getNext();
                }
                pointer2 = (Nodo) pointer.getNext();
                pointer2.setNext(null);
                pointer.setNext(getHead());
