//prime_fib returns n-th number that is a Fibonacci number and it's also prime.
// >>> prime_fib(1)
// 2
// >>> prime_fib(2)
// 3
// >>> prime_fib(3)
// 5
// >>> prime_fib(4)
// 13
// >>> prime_fib(5)
// 89
function prime_fib(n){
    function isPrime(number){
        if(number <= 3){
            return number > 1;
        }
        else if(number % 2 == 0 || number % 3 == 0){
            return false;
        }
        else{
            for(var i = 5; i * i <= number; i += 6){
                if(number % i == 0 || number % (i + 2) == 0){
                    return false;
                }
            }
            return true;
        }
    }
    function fib(num){
        var a = 1, b = 0, temp;

        while (num >= 0){
            temp = a;
            a = a + b;
            b = temp;

        }

        return b;
    }
    var res = 0;
    var fibNum = 0;
    while(res < n){
        if(isPrime(fib(fibNum))){
            res++;
        }
        fibNum++;
    }
    return fib(fibNum - 1);
}

