//Given a positive integer n, return the product of the odd digits.
// Return 0 if all digits are even.
// For example:
// >>> digits(1)
// 1
// >>> digits(4)
// 0
// >>> digits(235)
// 15
function digits(n){
    if(!n){
        return "error";

    if(n < 0){
        return "error";
    }
    var temp = 0;
    var prod = 1;
    var odd = true;
    for(n; n > 0; n = Math.floor(n/10)){
        temp = n % 10;
        if(temp % 2 != 0){
            prod *= temp;
            odd = false;
        }
    }
    if(odd){
        return 0;
    }
    return prod;
}

